      vertexData[offset++] = 0.5;
      vertexData[offset++] = extendedEndX + normalX;
      vertexData[offset++] = extendedEndY + normalY;
      vertexData[offset++] = 0.5;
      vertexData[offset++] = 0.5;
      vertexData[offset++] = extendedStartX - normalX;
      vertexData[offset++] = extendedStartY - normalY;
      vertexData[offset++] = 0.5;
      vertexData[offset++] = 0.5;
      vertexData[offset++] = extendedStartX - normalX;
      vertexData[offset++] = extendedStartY - normalY;
      vertexData[offset++] = 0.5;
      vertexData[offset++] = 0.5;
      vertexData[offset++] = extendedEndX + normalX;
      vertexData[offset++] = extendedEndY + normalY;
      vertexData[offset++] = 0.5;
      vertexData[offset++] = 0.5;
      vertexData[offset++] = extendedEndX - normalX;
      vertexData[offset++] = extendedEndY - normalY;
      vertexData[offset++] = 0.5;
      vertexData[offset++] = 0.5;
