      const centerDstH = dh - top - bottom;
      this.drawImageWithSourceAndDestination(image, 0, 0, sw, top, dx, dy, dw, top + 1);
      this.drawImageWithSourceAndDestination(image, 0, top, sw, centerSrcH, dx, dy + top, dw, centerDstH + 1);
