      rowPaint.setColor(new Color(0, 0, 0, 0));
      rowPaint.setRoundSize(6);
      const rowButton = rowNode.addComponent(UIButton);
      rowButton.setPressedTintColor(new Color(1, 1, 1, 0.08));
