  #messageQueue;
  /** @private @type { string } */
  #phase;
  // "hidden" | "enter" | "hold" | "exit"
  /** @private @type { number } */
  #phaseSeconds;
  /** @private @type { number } */
  #holdSeconds;
  /** @private @type { number } */
  #restY;
  /** @private @type { number | null } */
  #restX;
  // null 이면 부모 가로 중앙.
  /** @private @type { number } */
  #riseDistance;
